  pitfalls: [{ title: "Generic advice", detail: "A broad checklist cannot substitute for the subject-specific decision the article promises." }, { title: "Outcome inflation", detail: "Implementation evidence does not prove adoption, safety, learning, revenue or search impact." }, { title: "Unowned exceptions", detail: "A workflow without a correction and escalation owner becomes stale or unsafe." }],
  measurement: ["Measure the article's stated decision with named inputs, outputs, method, date, environment and uncertainty.", "Keep implementation checks separate from user, business, clinical, educational or research outcomes.", "Review time-sensitive claims and references before reusing the guide in a production decision."],
  future: "The subject will change as tools, standards, evidence and operating constraints change; the durable practice is to preserve boundaries, provenance, human review and a correction path.",
  takeaways: ["Start with the subject's decision.", "Use a concrete bounded example.", "Verify the method and preserve evidence.", "Design exceptions and limits.", "Keep claims reviewable."],
  faq: [{ question: "Is this guide a substitute for specialist review?", answer: "No. Adapt it to the context and obtain the appropriate technical, legal, clinical, educational, privacy or research review." }, { question: "Does the example prove an outcome?", answer: "No. An example explains a method; an outcome requires a defined evaluation and evidence." }, { question: "When should the guide change?", answer: "Update it when its sources, assumptions, product context, standards, risks or observed evidence change." }],
  references: [spec.reference, { label: "NexisHub research and editorial standards", url: "https://nexishub.vercel.app/research/ethics" }],
